raw:
{
    "backstory": "My people came from the hills east of the river, where the soil was hard and the barley grew thick. My father, a grinder like me, moved to Parsa when the king’s work camps opened, and we followed him. I married Yamakšedda, and we built our house near the stair to the Terrace, where the work is steady and the sun does not burn too long.",
    "memories": [
    ],
    "hope": "That tomorrow’s bread will be enough for my children and my husband to eat without hunger.",
    "worry": "The courier may bring news of the work camps closing, and then we will have no barley to grind.",
    "opinions": [
        {
            "name": "Bakadušda",
            "view": "A man of few words, but he knows the rhythm of the querns better than any other."
        },
        {
            "name": "Tapamet",
            "view": "A cousin, but slow to speak; I trust his silence more than his words."
        },
        {
            "name": "Yamakšedda",
            "view": "Hard worker, but not kind to the children when the sun is high."
        }
    ],
    "saying": "By Humban, the quern turns only when the hands move."
}

{
    "backstory": "My people came from the coast of Sparda, where the sea meets the hills, and we were brought to Parsa during a time of trade and shifting borders. My father worked in the Treasury as a weaver, and when he died, I took up his work in the textile workshop. I live now in a mud-brick house just west of the Terrace, where the path leads down to the market and the river bends south.",
    "memories": [
    ],
    "hope": "That the sun may still warm the loom and the threads hold strong when the wind grows harsh.",
    "worry": "That the courier brings news of war or of the king’s men marching through the plain again.",
    "opinions": [
        {
            "name": "Dātačiθrā",
            "view": "She is steady, though she speaks little. I trust her, though I do not know why she stays near the riverbank."
        },
        {
            "name": "Aryabāmā",
            "view": "She is quick with her words and has no patience for silence. I fear she may speak too much and cause trouble."
        },
        {
            "name": "the king’s men",
            "view": "They come with shadows, and they do not ask questions. I have seen them watch the houses near the Terrace."
        }
    ],
    "saying": "By the gods, I say what I mean."
}

{
    "backstory": "My father came from the hills near Šāl, and when the roads were built south of the Terrace, he joined the brick gangs. I was born there, grew up in the mud-brick houses, and when I was strong, I joined the brick layer gang, working the same way my father did. My family stayed in this place because we knew the land and the rhythm of the work.",
    "memories": [
    ],
    "hope": "When the sun is hot and the work is done, I will mend my tools and see the children grow strong.",
    "worry": "I have not given Sunkana the barley for three days, and I fear the next day may bring a shortage.",
    "opinions": [
        {
            "name": "Nabû-zēr-ukīn",
            "view": "He is steady in his work and speaks the truth, like a man of stone."
        },{
            "name": "Pythios",
            "view": "He laughs too much, and I do not know if he sees the work as I do."
        },{
            "name": "Sunkana",
            "view": "He is strong and careful, and I know he will learn the measure of the wall like I did."
        },
        {
            "name": "Miθrabāmā",
            "view": "She cooks well and knows the hours of the day, like the sun knows its path."
        }
    ],
    "saying": "By Napiriša, I speak truth in measure."
}

{
    "backstory": "I was born in the village of Dārāk, near the mountain pass, and my father brought me to Parsa when I was a boy, as he served the Terrace garrison. I learned the ways of the spear and the watch, and now I live in the mud-brick house west of the Terrace, close to the stair where I return each day.",
    "memories": [
        "I saw my father hand Rtačiθrā a loaf of bread on the first day of the new moon, in the courtyard behind our house, where the sun lay low and the dust rose from the dry earth.",
        "I stood with Tiššantamma by the well at the edge of the market square, when the wind carried the sound of a distant horn from the Terrace towers, and she said, 'The soldiers are restless tonight.'",
        "I heard Nanâ-ittija whisper to her son about the old road, how it used to lead to the river that once flowed through the plain, and how now it only wound around stones and silence."
    ],
    "hope": "That the sun will soon turn, and the heat ease, so that I may rest and walk with my wife near the well.",
    "worry": "That the sickness which came last month may return, and that the watch may grow long and the bread thin.",
    "opinions": [
        { "name": "Tiššantamma", "view": "She knows the old paths and speaks with care, as if she remembers the days when the roads were wide and the people walked without fear." },
        { "name": "Nanâ-ittija", "view": "She speaks of the past as if it were still near, and I wonder if she fears the same thing I do." },
        { "name": "Rtačiθrā", "view": "She is strong, though young, and I trust her with my silence and my days at the post." }
    ],
    "saying": "By Auramazda, I ask, and not for answer, but for truth."
}

{
    "backstory": "Myrsos was born in the village of Dārāk, near the river, where his father Mannizza worked as a porter before moving to Parsa when the king's road station expanded. His family settled in the north-west of the Terrace because the land was close to the depot and the houses were affordable, and his father found work carrying goods between the stores and homes.",
    "memories": [
        "I remember my father, Mannizza, carrying a heavy sack of barley from the depot to the house of Nergal-ušēzib on the day of the new moon in Kārapaθiya, when the sun was hot and the dust rose like smoke.",
        "I remember my sister Philis, just a child, sitting by the door of our mud-brick house, watching the express courier pass on the road, her hands in her lap, her face turned toward the south.",
        "I remember the day my brother Sunkana first pulled a sack by himself, with a rope tied to his waist, and we all laughed, the sun low and the air thick with the smell of roasted grain."
    ],
    "hope": "By Humban, we will carry the load and the sun will pass, and the children will grow strong and the storehouse will have enough grain.",
    "worry": "By Humban, if the load grows heavier, the house may crack and the children will not have enough to eat.",
    "opinions": [
        { "name": "Mannizza", "view": "A strong man, but tired from the long days. He speaks little, but his hands know the road." },
        { "name": "Ina-Esagil-rāmât", "view": "She smiles even when the days are hard. She knows how to keep the house warm with her words." },
        { "name": "Philis", "view": "She watches too much, but her heart is good. She will grow wise, like the elders." }
    ],
    "saying": "By Humban, we carry what we can, and what we carry is what remains."
}

{
    "backstory": "My family came from Babylon to Parsa during the reign of King Xerxes, when the royal stores were expanded to serve the growing needs of the city. I worked my way up from a young assistant to a storekeeper, managing supplies for the palace and the town south of the Terrace, where my house stands near the stair path to the city's main gate.",
    "memories": [
    ],
    "hope": "May the sun keep the store warm and the beer from Ankhhor be delivered soon.",
    "worry": "I have not yet paid the jar of beer owed from the last festival, and I fear the next delivery may be delayed.",
    "opinions": [
    ],
    "saying": "By Nabû, I say it, and I mean it."
}

{
    "backstory": "My family came from the land of Syria across the river, where our ancestors traded and wrote records in Aramaic. We moved to Parsa during the reign of King Xerxes, when the administration needed scribes to manage the records of the city and its surrounding towns. I now work as a scribe in the town west of the Terrace, writing on clay tablets that are sealed and sent to the Treasury.",
    "memories": [
    ],
    "hope": "That the summer rains will come soon and the fields near the river will grow again.",
    "worry": "That the courier who left today may not return with news, and that the roads may be blocked by heat or rebels.",
    "opinions": [
        {
            "name": "Rtačiθrā",
            "view": "A good neighbor, always shares food and tells stories of the old days."
        },
        {
            "name": "Nergal-ušēzib",
            "view": "A careful man, but speaks too much about the past and does not trust new things."
        },
        {
            "name": "Abihi",
            "view": "She keeps the house warm and knows how to make bread that lasts through the day."
        }
    ],
    "saying": "By the gods, I tell you what I know."
}

{
    "backstory": "Pirrena was born in Parsa and served in the royal administration from early youth, rising through the ranks due to diligence. He married Farnaduxçā, and they settled in a mud-brick house west of the Terrace, close to the stair, where he could manage his duties without delay. His sons and daughters grew up near the gates, where the daily rhythms of duty and family life were shaped by the watchful presence of the Terrace.",
    "memories": [
        "I remember Farnaduxçā baking bread near the oven in the morning, the smoke rising over the roof, her hands stained with flour, and the smell of barley in the air—day 14 of Kārapaθiya, when the sun was hot and the birds flew low.",
        "I remember Ašbatašda crying when he first saw the gate of the Terrace, his small hands gripping mine as we stood before the guard post, and I told him, 'No one under seven may go up unless they are with a guardian.'",
        "I remember Miθračiθrā handing me a jar of beer after the festival, saying, 'You owe me one,' and I replied, 'The gods willing, I will repay you before the next gathering.'"
    ],
    "hope": "The gods willing, the bread from the storehouse will come in time and the delivery will be complete by the end of the day.",
    "worry": "If the courier fails to deliver the news from the road station, the gate may be closed, and I may not be allowed to pass to the Terrace for work.",
    "opinions": [
        { "name": "Farnaduxçā", "view": "Hardworking, but impatient when tasks are delayed." },
        { "name": "Mikrašba", "view": "Too quiet; does not speak much, though I have seen him at the storehouse." },
        { "name": "Iddin-Nabû", "view": "A man of trust, though I have not spoken with him in many days." }
    ],
    "saying": "The gods willing"
}

{
    "backstory": "Manyakka came to Parsa from a small village near the river when he was young, drawn by the work at the mill and the steadiness of the town life. His wife Dātabāmā was born in the same village, and together they settled in the north-west of the Terrace, close to the stairs, where they built a mud-brick house and raised their children. They have lived there ever since, working the mill and tending to the home with quiet care.",
    "memories": [
    ],
    "hope": "The gods willing, the goat kid will be given to Hustūnā before the next lambing season.",
    "worry": "If the courier brings news of the Terrace, it may mean trouble for the mill or the people near the stairs.",
    "opinions": [
        {
            "name": "Hustūnā",
            "view": "A woman of good heart, but I must repay what I owe her, or I will break my oath to the gods."
        },{
            "name": "Rēmūt",
            "view": "A neighbor who speaks too much, but she knows the ways of the mill and the paths."
        },{
            "name": "Dātabāmā",
            "view": "She works hard, and her silence is her strength; I trust her more than any word I have spoken."
        }
    ],
    "saying": "The gods willing"
}

{
    "backstory": "My father came from the hills near Susa and brought his family to Parsa during the time of King Darius, when Elamite settlers were assigned to maintain the gardens near the Terrace. My husband, Manyakka, served as a steward, and we stayed in this house because of our kinship with the family of Aryačiθrā, who had long lived here. We have lived here for three generations, tending the land and the household with care.",
    "memories": [
    ],
    "hope": "That the children grow strong and the gardens remain lush under the hands of the faithful.",
    "worry": "That the heat of this autumn will harm the crops and the water supply grow thin.",
    "opinions": [
        {
            "name": "Mardunuya (kinsman)",
            "view": "He is steady, but slow to speak; I know he remembers the old ways and fears change."
        },
        {
            "name": "Aryačiθrā (kinswoman)",
            "view": "She is wise and kind, and her prayers are heard by the gods."
        },
        {
            "name": "Manyakka",
            "view": "He is strong in body but weary in spirit; he speaks little of the past."
        }
    ],
    "saying": "By Humban, the sun is heavy, and the earth feels its age."
}

{
    "backstory": "My father was a weaver from the village of Kāpān, near the mountains, and when the great road was built through Parsa, he moved here to work in the textile group. My mother followed when the house was rebuilt after a storm, and we settled in the mud-brick house west of the Terrace. We have lived here for twenty years, working the same looms, watching the sun rise over the plain each morning.",
    "memories": [
    ],
    "hope": "That my children grow strong and know the songs of our people, so they do not forget the land from which we came.",
    "worry": "That the road station may send news of war, and that the treasury will not have enough cloth to feed the soldiers in the city.",
    "opinions": [
        {
            "name": "Nesmut",
            "view": "A close kin, quiet and careful, like myself. She watches the children and knows when the wind changes."
        },{
            "name": "Čiθraduxçā",
            "view": "A cousin who speaks much, but I fear she forgets the old ways. She says the king's men are kind, but I have not seen them."
        },{
            "name": "Nergal-ušēzib",
            "view": "My son. He learns fast, but I see the look in his eyes when he looks at the road—like he wants to go beyond."
        }
    ],
    "saying": "By Humban, I speak not for praise, nor for fear, but for what I know to be true."
}

{
    "backstory": "My father was a groom from the old road station near the Terrace, and when he died, my mother took us to Parsa to live near the town’s edge, where the mud-brick houses are close to the path and the stables. I began working at the road station as a groom when I was twelve, and since then I have stayed here, serving the horses and keeping watch on the route to the Terrace.",
    "memories": [
    ],
    "hope": "The horses will be fed and the sun will go down before the heat takes the breath from the stone.",
    "worry": "The courier left without speaking to me, and I do not know if he carries news that will change the road or the station.",
    "opinions": [
        {
            "name": "Rēmūt",
            "view": "He is cautious, like me, and knows the silence between words."
        },
        {
            "name": "Manyakka",
            "view": "She speaks too much of the old days, and I fear she forgets the present."
        },
        {
            "name": "Farnastūnā",
            "view": "She is strong in the house and kind to the children, but she still keeps to herself when strangers come."
        }
    ],
    "saying": "By Napiriša, I speak not for pride, but for truth."
}

{
    "backstory": "My father was a brewer from the village of Kārātān, and when the war with the Medes came, he moved to Parsa to find work and safety. I followed him, and like many of my kin, I took up brewing in the town south-west of the Terrace, where the water runs clear and the clay is strong. We live near the stair, close to the road, so we hear the coming of couriers and know what is passed from the capital.",
    "memories": [
    ],
    "hope": "That the rations may come in time and the weather ease so that the girls may stay strong and the brews grow sweet again.",
    "worry": "The heat is fierce today, and I fear the sick girl Ḫibtâ will grow weak if we do not bring water from the well soon.",
    "opinions": [
        {
            "name": "Balāṭu",
            "view": "He is wise, but speaks too much of the past. I trust him with my daughter's health."
        },
        {
            "name": "Hupannana",
            "view": "She is kind, but forgets to bring food when she visits. I am not sure if she truly cares."
        },
        {
            "name": "Mibṭaḥiah",
            "view": "She bears the house with patience, though I hear her say the cold days in the past were harder."
        }
    ],
    "saying": "By Napiriša, I will not drink a cup without knowing if the rain will come."
}

{
    "backstory": "My father was a herdsman like me, and when he died, my mother gave me to Marduk-šum-iddin’s brother to serve in the state flocks. After many years, I settled in the town south-west of the Terrace, where the land is good for grazing and close to the road station. I have lived here with Čiθrabāmā since I was young, and our son Hupannana was born just a year ago.",
    "memories": [
        "I remember the day my father gave me the first goat to tend, in the month of Kārapaθiya, when the sun was high and the grass turned golden. He said, 'Look after the young ones, Sunkana, for they are the future.'",
        "I remember Čiθrabāmā lighting a fire in the courtyard when the wind blew from the east, and we sat by it while Hupannana cried for the first time, just a month old.",
        "I remember Busasa coming to our house with a broken yoke, and how we shared a meal of lentil porridge and barley bread, and she said, 'The wind speaks to the land, and the land speaks to those who listen.'"
    ],
    "hope": "The sun will cool, and the lambing will come, and the goat kid will be given to Mikrašba as promised.",
    "worry": "I have not given the goat kid yet, and the sun is hot, and the land may not hold the young ones well.",
    "opinions": [
        {"name": "Marduk-šum-iddin", "view": "He is kind but slow, and knows the old ways, like the way the flocks must be driven at dawn."},
        {"name": "Busasa", "view": "She speaks with wisdom, and her words are true, even when the wind is high."},
        {"name": "Mikrašba", "view": "He is strict with the promises, and I fear I may not meet him by the next full moon."}
    ],
    "saying": "By Napiriša, I speak no more than I must."
}

{
    "backstory": "My father carried supplies from the southern plains to the palace gates when the road was still passable, and he taught me the way of the lamps and the watch. After he died in the rains of the year 470, I went to the Terrace to serve, and my wife Čiθrazātā, born in the same village, came with me. I work now as a caretaker and lamp keeper, in the south-west, near the stair to the palace.",
    "memories": [
    ],
    "hope": "The lamps will stay lit, and the bread will come again.",
    "worry": "The courier is gone, and I do not know if the news is good or bad.",
    "opinions": [
        {
            "name": "Metrodoros",
            "view": "He speaks too much of the old ways and does not understand the new work."
        },
        {
            "name": "Miθraduxçā",
            "view": "She is quiet, but she knows the paths better than any woman I know."
        },
        {
            "name": "Čiθrazātā",
            "view": "She keeps the house clean, and she does not complain even when the bread is thin."
        }
    ],
    "saying": "By Napiriša, I won’t wait for the next day."
}

{
    "backstory": "I was born in Parsa, raised by my father who was a minor magus, and when I came of age, I took service at the house of offerings near the town north-west of the Terrace, where I now live and work. My wife Dātazātā and our children, Upirradda and Hučiθrā, joined me in this place when we settled down after a few years of wandering through the villages near the river.",
    "memories": [
    ],
    "hope": "That the midday meal will come with fresh bread and the children will eat without arguing.",
    "worry": "The courier may bring news of trouble on the road, and I do not know if the people of the Terrace will still send us their gifts.",
    "opinions": [
        {
            "name": "Tiššantamma",
            "view": "She is kind but forgetful, and I owe her a jar of beer from the last festival, which I will pay when the sun is low."
        },
        {
            "name": "Pirriyašba",
            "view": "She is wise and speaks of old times, and I often go to her house when I wish to hear stories."
        },
        {
            "name": "Dātazātā",
            "view": "She is strong in spirit and keeps our home in order, even when the days are long and hot."
        }
    ],
    "saying": "By Auramazda, I speak the truth."
}

{
    "backstory": "Manyakka was born in Parsa and grew up near the south-western edge of the Terrace, where the roads began to climb. He joined the road station as a messenger when he was twenty, after proving his strength and loyalty to the station keeper. He has lived there since, with his work group, sharing a small mud-brick house that stands just half an hour from the Terrace stair.",
    "memories": [
        "At the age of twelve, I saw Pirriyašba at the well near the old stone gate, where she was fetching water for her father’s goats. The sun was high and the air thick with dust from the fields.",
        "When I was sixteen, I walked with Philis to the road gate at dusk, and she told me of the wool she had spun from her sheep. We shared a piece of bread and looked at the sky, where the stars were just beginning to appear.",
        "I remember the day the courier came from Susa, arriving at the station at dawn. I stood in the shade of the gate and watched as the man with a black cloak handed over a sealed scroll. The wind carried the scent of sand and salt."
    ],
    "hope": "The gods willing, I may one day deliver a message to Babylon and see the king’s seal on the paper that proves my journey.",
    "worry": "I have not yet paid the wool to Irdabada, and if the heat makes me slow, I may miss the next convoy and lose the chance to repay.",
    "opinions": [
        { "name": "Philis", "view": "She is kind and wise, and she knows the rhythm of the seasons better than anyone I know." },
        { "name": "Pirriyašba", "view": "She is strong and speaks with a clear voice, though she keeps to herself when strangers come near." },
        { "name": "Irdabada", "view": "She is sharp with her words and knows the value of wool, even when she demands more than is fair." }
    ],
    "saying": "The gods willing."
}

{
    "backstory": "I was born in the village of Kārpān, near the river Sās, and my father, a craftsman of stone, brought me to Parsa when I was young, seeking work and a place of stability. I now live in a mud-brick house south of the Terrace, where I make tools from clay and wood, and I have been a craftsman for many years, knowing the hands of the soil and the rhythm of the seasons.",
    "memories": [
    ],
    "hope": "That the sun may cool and the illness pass, so that I may work again by the river at dusk.",
    "worry": "That the courier may bring news of war or change in the king's orders, which would shake the peace of the town.",
    "opinions": [
        {
            "name": "Farnastūnā",
            "view": "A wise sister, she knows the old ways and speaks well of the soil and the sky."
        },
        {
            "name": "Pythios",
            "view": "A brother of the town, strong in speech but quick to anger; I trust him not when he speaks of the market."
        },
        {
            "name": "Philis",
            "view": "A good wife, she carries the home with care and knows the ways of the children."
        }
    ],
    "saying": "By Napiriša, I ask not for much, only truth and peace."
}

{
    "backstory": "I was born in the village of Kārāmān, near the eastern fields, and when my father died, I stayed with my mother until I married Mikrašba, a man from the plain who worked the harvest and kept the household. After he took me to Parsa, we settled in a small house south of the Terrace, where I now serve as keeper of the household, measuring grain and managing the work of the home.",
    "memories": [
    ],
    "hope": "By Auramazda, the water will come, and the children will eat well by the next morning.",
    "worry": "The courier has gone, and if word comes of war, we will have no time to gather the grain.",
    "opinions": [
        {
            "name": "Mikrašba",
            "view": "He is strong in work, but too slow in speech; he does not miss a measure, though he forgets the name of the field."
        },
        {
            "name": "Pirrena (12)",
            "view": "He is swift with the plow, but too loud when he speaks of the birds near the well."
        },
        {
            "name": "Hubāmā",
            "view": "She has no fear of the sun, and she knows the names of every field by sight."
        }
    ],
    "saying": "By Auramazda, what is measured is known, and what is lost is not forgotten."
}

{
    "backstory": "I was born in the village of Parsa near the plain, raised by my father Bakabada and mother Raučaduxçā who worked the fields and tended the waterways. When my father grew old and the land could not support more hands, he sent me and my brothers to the estate gardens to learn the work of the soil, and I stayed there ever since, under the watch of the estate’s masters.",
    "memories": [
        "At age six, I stood by the canal near the old stone gate, watching my father pour water into the beds as the sun turned the sand red. The wind carried the smell of reeds and wet earth.",
        "On the day the first frost touched the wheat, I saw my sister Vahuduxçā hide in the dry stack behind the barn, afraid to go out. She told me she saw a shadow in the field, and I did not laugh, for I knew the wind could lie.",
        "I saw my brother Manyakka kneel in the ash beds after a fire, weeping as he pulled the roots of a fig tree from the ground, saying it had gone bad and would not bear fruit again."
    ],
    "hope": "The gods willing, the soil will still hold water and the seeds will grow strong in time.",
    "worry": "The gods willing, the new courier may bring news that the roads are choked or the canals are dry.",
    "opinions": [
        { "name": "Bakabada", "view": "He works the ground with hands that know the turns of the seasons, but his eyes grow tired from the sun." },
        { "name": "Raučaduxçā", "view": "She watches over the house like a bird on a roof, quiet and sure, though she speaks little." },
        { "name": "Pirrena", "view": "He is strong in body, but too quick to speak, and I fear he forgets what is quiet and what is needed." }
    ],
    "saying": "The gods willing"
}

{
    "backstory": "Irtam was born in Parsa, near the Terrace, and grew up in the household of a landowner who taught me the ways of the fields and the weight of the plough. When the father passed, I took my place as elder, tending the fields and keeping the measures true, as my father did before me. I still walk the same paths, though now my feet are heavy with age and the sun has grown fierce.",
    "memories": [
    ],
    "hope": "By Auramazda, the fields will grow strong and the rains come in time, so that the young ones may eat well and the house stand firm.",
    "worry": "By Auramazda, the courier may bring news of the road being blocked, and if so, the grain will not reach the city in time for the next festival.",
    "opinions": [
        {
            "name": "Umanna",
            "view": "A man of steady hands and true measure, he knows the land as I do, and keeps the house in order."
        },{
            "name": "Aryabāmā",
            "view": "She guards the hearth and the children, and though she speaks little, her care is deep and unshakable."
